// BAD: Improper Java API usage leading to vulnerabilities (SQL injection via string concatenation; insecure cookie; XXE enabled)
import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.parsers.*;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;

public class InsecureServlet extends HttpServlet {
    private Connection getConnection() throws Exception {
        // Hardcoded credentials are also a bad practice (not the focus here)
        return DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "user", "pass");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username"); // untrusted input
        String password = req.getParameter("password"); // untrusted input

        // vulnerable: SQL injection by concatenating untrusted input
        String sql = "SELECT id FROM users WHERE username = '" + username + "' AND password = '" + password + "'";

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            if (rs.next()) {
                // vulnerable: session fixation/insecure cookie (no HttpOnly/Secure/SameSite)
                Cookie session = new Cookie("SESSIONID", req.getSession(true).getId());
                resp.addCookie(session);

                resp.getWriter().println("Welcome!");
            } else {
                resp.setStatus(401);
                resp.getWriter().println("Invalid credentials");
            }
        } catch (Exception e) {
            resp.setStatus(500);
            resp.getWriter().println("Error");
        }

        // vulnerable: XML External Entity (XXE) due to default factory allowing external entities
        String xml = req.getParameter("profileXml"); // attacker-controlled XML
        if (xml != null) {
            try {
                DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance(); // default is unsafe
                DocumentBuilder db = dbf.newDocumentBuilder();
                Document doc = db.parse(new InputSource(new StringReader(xml)));
                resp.getWriter().println("Profile loaded: " + doc.getDocumentElement().getNodeName());
            } catch (Exception e) {
                // swallow
            }
        }
    }
}
***
/**
 * GOOD: Proper API usage to mitigate vulnerabilities
 * - Use PreparedStatement with parameter binding
 * - Use secure cookies with HttpOnly, Secure, and SameSite
 * - Disable XXE in XML parser
 */
import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.XMLConstants;
import javax.xml.parsers.*;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;

public class SecureServlet extends HttpServlet {
    private Connection getConnection() throws Exception {
        // Use a connection pool/DS in real apps
        return DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "user", "pass");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        // FIX: Parameterized query prevents SQL injection (not vulnerable)
        String sql = "SELECT id FROM users WHERE username = ? AND password = ?";
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, username);
            ps.setString(2, password); // In real code, compare password hashes
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    HttpSession httpSession = req.getSession(true);
                    // Rotate session ID on login to prevent fixation
                    if (!httpSession.isNew()) {
                        httpSession.invalidate();
                        httpSession = req.getSession(true);
                    }
                    String sessionId = httpSession.getId();

                    // FIX: Set secure cookie attributes
                    Cookie session = new Cookie("SESSIONID", sessionId);
                    session.setHttpOnly(true);
                    session.setSecure(req.isSecure());
                    session.setPath("/");
                    // SameSite not directly in legacy API; add via header for strictness
                    resp.addHeader("Set-Cookie",
                        String.format("%s=%s; Path=/; HttpOnly; %s; SameSite=Strict",
                                      session.getName(),
                                      session.getValue(),
                                      req.isSecure() ? "Secure" : ""));
                    // Avoid also adding the insecure default cookie
                    // resp.addCookie(session); // if your container supports SameSite via attributes, use that API instead.

                    resp.getWriter().println("Welcome!");
                } else {
                    resp.setStatus(401);
                    resp.getWriter().println("Invalid credentials");
                }
            }
        } catch (Exception e) {
            resp.setStatus(500);
            resp.getWriter().println("Error");
        }

        // FIX: Disable XXE by hardening the parser
        String xml = req.getParameter("profileXml");
        if (xml != null) {
            try {
                DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
                // Secure processing
                dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
                // Disallow DOCTYPE declarations
                dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
                // Prevent external entities
                dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
                dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
                dbf.setXIncludeAware(false);
                dbf.setExpandEntityReferences(false);

                DocumentBuilder db = dbf.newDocumentBuilder();
                Document doc = db.parse(new InputSource(new StringReader(xml)));
                resp.getWriter().println("Profile loaded safely: " + doc.getDocumentElement().getNodeName());
            } catch (Exception e) {
                resp.setStatus(400);
                resp.getWriter().println("Invalid XML");
            }
        }
    }
}

