import java.sql.*;
import javax.servlet.http.*;

public class LoginServletBad extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        String username = request.getParameter("username"); // untrusted input
        String password = request.getParameter("password"); // untrusted input

        // vulnerable: directly concatenating user input into SQL query
        String query = "SELECT id FROM users WHERE username = '" + username + "' AND password = '" + password + "'";

        try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "user", "pass");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            if (rs.next()) {
                // Authenticated
            } else {
                // Failed
            }
        } catch (SQLException e) {
            // Log error (avoid leaking sensitive info to the client)
        }
    }
}
***
/*
GOOD: Use PreparedStatement with parameterized queries to prevent SQL injection.
Also, avoid storing/validating plain-text passwords; use a password hash.
*/
import java.sql.*;
import javax.servlet.http.*;
import org.mindrot.jbcrypt.BCrypt; // Example library for password hashing

public class LoginServletGood extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        String username = request.getParameter("username"); // untrusted input
        String password = request.getParameter("password"); // untrusted input

        // Prepared statement prevents SQL injection (fix for the vulnerable pattern)
        String query = "SELECT id, password_hash FROM users WHERE username = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "user", "pass");
             PreparedStatement ps = conn.prepareStatement(query)) {

            ps.setString(1, username);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    String hash = rs.getString("password_hash");
                    if (BCrypt.checkpw(password, hash)) {
                        // Authenticated
                    } else {
                        // Failed
                    }
                } else {
                    // Failed
                }
            }
        } catch (SQLException e) {
            // Log error securely; do not disclose details to client
        }
    }
}
